import sys

MOD = 998244353

def dp_chaotic_merge(x, y):
    n, m = len(x), len(y)
    dp = [[[0] * (m + 1) for _ in range(n + 1)] for __ in range(n + m + 1)]
    dp[0][0][0] = 1

    for total in range(1, n + m + 1):
        for i in range(total + 1):
            j = total - i
            if i < n:
                dp[total][i + 1][j] += dp[total][i][j]
                dp[total][i + 1][j] %= MOD
                if j > 0 and x[i] != y[j - 1]:
                    dp[total][i + 1][j] += dp[total - 1][i][j - 1]
                    dp[total][i + 1][j] %= MOD
            if j < m:
                dp[total][i][j + 1] += dp[total][i][j]
                dp[total][j][j + 1] %= MOD
                if i > 0 and y[j] != x[i - 1]:
                    dp[total][i][j + 1] += dp[total - 1][i - 1][j]
                    dp[total][i][j + 1] %= MOD

    return dp[n + m][n][m]

